"use client";

import { useEffect, useState, useCallback } from "react";
import { useSession } from "next-auth/react";
import { hireRequestsApi, workUpdatesApi } from "@/lib/api";
import { HireRequest, HireRequestStatus, WorkUpdate } from "@/types";
import { EmployerHireRequestsList } from "@/components/employer/EmployerHireRequestsList";
import { WorkUpdatesDrawer } from "@/components/work/WorkUpdatesDrawer";
import { CardSkeleton } from "@/components/ui/Skeleton";
import { FileText } from "lucide-react";
import { cn } from "@/lib/utils";

type TabId = "pending" | "accepted" | "rejected";

const TABS: { id: TabId; label: string }[] = [
  { id: "pending",  label: "Pending"  },
  { id: "accepted", label: "Accepted" },
  { id: "rejected", label: "Rejected" },
];

export default function EmployerHireRequestsPage() {
  const { data: session, status } = useSession();
  const [requests, setRequests]   = useState<HireRequest[]>([]);
  const [loading, setLoading]     = useState(true);
  const [activeTab, setActiveTab] = useState<TabId>("pending");
  const [updateCounts, setUpdateCounts] = useState<Record<string, number>>({});

  // Drawer state — opened when employer clicks "View Progress"
  const [drawerTarget, setDrawerTarget] = useState<{ refId: string; title: string } | null>(null);

  const fetchRequests = useCallback(async () => {
    if (!session?.user.accessToken) { setLoading(false); return; }
    setLoading(true);
    try {
      const res = (await hireRequestsApi.getEmployerRequests(
        session.user.accessToken
      )) as { data: HireRequest[] };
      const data = res.data || [];
      setRequests(data);

      // Batch-fetch update counts for accepted requests
      const accepted = data.filter((r) => r.status === "accepted");
      const countMap: Record<string, number> = {};
      await Promise.allSettled(
        accepted.map(async (r) => {
          try {
            const r2 = (await workUpdatesApi.getByRef(
              session.user.accessToken!,
              "hireRequest",
              r._id
            )) as { data: WorkUpdate[] };
            countMap[r._id] = r2.data?.length ?? 0;
          } catch {
            countMap[r._id] = 0;
          }
        })
      );
      setUpdateCounts(countMap);
    } catch {
      setRequests([]);
    } finally {
      setLoading(false);
    }
  }, [session]);

  useEffect(() => {
    if (status === "loading") return;
    fetchRequests();
  }, [fetchRequests, status]);

  const counts: Record<TabId, number> = {
    pending:  requests.filter((r) => r.status === "pending").length,
    accepted: requests.filter((r) => r.status === "accepted").length,
    rejected: requests.filter((r) => r.status === "rejected").length,
  };

  const filtered: HireRequest[] = requests.filter(
    (r) => r.status === (activeTab as HireRequestStatus)
  );

  return (
    <div className="space-y-6">
      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div>
          <h2 className="text-xl font-bold text-gray-900">Hire Requests</h2>
          <p className="text-sm text-gray-400 mt-0.5">
            Manage hiring invitations you&apos;ve sent to job seekers
          </p>
        </div>
      </div>

      {/* ── Tab row ── */}
      <div className="bg-white rounded-xl border border-gray-200">
        <div className="px-4 sm:px-5 border-b border-gray-100 flex items-center gap-0.5 overflow-x-auto no-scrollbar scrollbar-none" role="tablist">
          {TABS.map((tab) => (
            <button
              key={tab.id}
              role="tab"
              aria-selected={activeTab === tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={cn(
                "flex items-center gap-1.5 px-4 py-3 text-sm font-medium border-b-2 transition-colors -mb-px whitespace-nowrap",
                activeTab === tab.id
                  ? "border-[#1e3a5f] text-[#1e3a5f]"
                  : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
              )}
            >
              {tab.label}
              <span
                className={cn(
                  "rounded-full px-1.5 py-0.5 text-xs",
                  activeTab === tab.id ? "bg-blue-100 text-[#1e3a5f]" : "bg-gray-100 text-gray-500"
                )}
              >
                {counts[tab.id]}
              </span>
            </button>
          ))}
        </div>

        {/* ── Content ── */}
        <div className="p-5">
          {loading ? (
            <div className="space-y-3">
              {Array.from({ length: 3 }).map((_, i) => <CardSkeleton key={i} />)}
            </div>
          ) : filtered.length === 0 ? (
            <div className="text-center py-16">
              <div className="w-14 h-14 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
                <FileText size={22} className="text-gray-400" />
              </div>
              <p className="text-sm font-medium text-gray-600 mb-1">
                No {activeTab} hire requests.
              </p>
              <p className="text-xs text-gray-400">
                {activeTab === "pending"  && "Send hire requests to job seekers to see them here."}
                {activeTab === "accepted" && "Accepted hire requests will appear here."}
                {activeTab === "rejected" && "Declined hire requests will appear here."}
              </p>
            </div>
          ) : (
            <EmployerHireRequestsList
              requests={filtered}
              onUpdate={fetchRequests}
              updateCounts={updateCounts}
              onViewProgress={(refId, title) => setDrawerTarget({ refId, title })}
            />
          )}
        </div>
      </div>

      {/* ── Progress drawer (employer read-only) ── */}
      <WorkUpdatesDrawer
        open={!!drawerTarget}
        onClose={() => setDrawerTarget(null)}
        refType="hireRequest"
        refId={drawerTarget?.refId ?? ""}
        title={drawerTarget?.title ?? ""}
        role="employer"
      />
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { useParams } from "next/navigation";
import { useSession } from "next-auth/react";
import Link from "next/link";
import { jobsApi, applicationsApi } from "@/lib/api";
import { Job, Application } from "@/types";
import { Badge, statusBadge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import {
  formatCurrency,
  formatDate,
  formatRelativeTime,
  salaryLabel,
} from "@/lib/utils";
import {
  ChevronLeft,
  Edit3,
  ExternalLink,
  BarChart2,
  MapPin,
  Briefcase,
  Users,
  Calendar,
  Clock,
  Building2,
  GraduationCap,
  User,
} from "lucide-react";

// ── helpers ──────────────────────────────────────────────────────────────────

const employmentLabels: Record<string, string> = {
  fullTime: "Full Time", partTime: "Part Time",
  contract: "Contract", internship: "Internship",
};
const shiftLabels: Record<string, string> = {
  day: "Day Shift", night: "Night Shift",
  rotating: "Rotating", flexible: "Flexible",
};
const expLabels: Record<string, string> = {
  fresher: "Fresher", "0-1": "0–1 Year", "1-2": "1–2 Years",
  "2-5": "2–5 Years", "5-10": "5–10 Years", "10+": "10+ Years",
};
const educationLabels: Record<string, string> = {
  any: "Any", highSchool: "High School",
  bachelor: "Bachelor's", master: "Master's", phd: "PhD",
};

function stripHtml(html: string): string {
  return html.replace(/<[^>]*>/g, "").trim();
}

// ── skeleton ─────────────────────────────────────────────────────────────────

function PanelSkeleton() {
  return (
    <div className="bg-white rounded-xl border border-gray-200 p-6 animate-pulse space-y-4">
      <div className="h-5 bg-gray-200 rounded w-1/3" />
      {[100, 80, 90, 70, 85].map((w) => (
        <div key={w} className="flex gap-4">
          <div className="h-4 bg-gray-200 rounded w-24 flex-shrink-0" />
          <div className="h-4 bg-gray-200 rounded" style={{ width: `${w}%` }} />
        </div>
      ))}
    </div>
  );
}

// ── detail row ───────────────────────────────────────────────────────────────

function Field({ label, value, className }: { label: string; value?: string | number | null; className?: string }) {
  if (!value && value !== 0) return null;
  return (
    <div className={`flex flex-col gap-1 ${className || ""}`}>
      <dt className="text-xs font-semibold text-gray-400 uppercase tracking-wide">
        {label}
      </dt>
      <dd className="text-sm text-gray-800 font-medium">{value}</dd>
    </div>
  );
}

// ── page ─────────────────────────────────────────────────────────────────────

export default function JobDetailPage() {
  const { id } = useParams<{ id: string }>();
  const { data: session } = useSession();
  const [job, setJob] = useState<Job | null>(null);
  const [applications, setApplications] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchAll = useCallback(async () => {
    if (!id || !session?.user.accessToken) return;
    setLoading(true);
    try {
      const [jobRes, appRes] = await Promise.all([
        jobsApi.getJobById(id) as Promise<{ data: Job }>,
        applicationsApi.getJobApplications(session.user.accessToken, id) as Promise<{ data: Application[] }>,
      ]);
      setJob(jobRes.data);
      setApplications(appRes.data || []);
    } catch {
      setJob(null);
    } finally {
      setLoading(false);
    }
  }, [id, session]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  // ── loading ────────────────────────────────────────────────────────────────
  if (loading) {
    return (
      <div className="space-y-6">
        <div className="h-4 bg-gray-200 rounded w-24 animate-pulse" />
        <div className="h-8 bg-gray-200 rounded w-1/2 animate-pulse" />
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <PanelSkeleton />
          <PanelSkeleton />
        </div>
        <PanelSkeleton />
      </div>
    );
  }

  if (!job) {
    return (
      <div className="text-center py-20">
        <p className="text-gray-500">Job not found.</p>
        <Link href="/employer/my-jobs" className="text-[#1e3a5f] text-sm hover:underline mt-2 inline-block">
          ← Back to My Jobs
        </Link>
      </div>
    );
  }

  const salaryDisplay =
    job.salaryMin && job.salaryMax
      ? `${formatCurrency(job.salaryMin)} – ${formatCurrency(job.salaryMax)}`
      : formatCurrency(job.salary);

  const accepted = applications.filter(a => a.status === "accepted").length;
  const pending  = applications.filter(a => a.status === "pending").length;

  return (
    <div className="space-y-6">

      {/* ── Breadcrumb ──────────────────────────────────────────────── */}
      <Link
        href="/employer/my-jobs"
        className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-700 transition-colors"
      >
        <ChevronLeft size={16} />
        My Jobs
      </Link>

      {/* ── Title row ───────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4">
        <div>
          <div className="flex flex-wrap items-center gap-2 mb-1">
            <h1 className="text-2xl font-bold text-gray-900">{job.title}</h1>
            <Badge variant={statusBadge(job.status)}>
              {job.status === "open" ? "Active" : job.status.charAt(0).toUpperCase() + job.status.slice(1)}
            </Badge>
          </div>
          <p className="text-sm text-gray-500">
            {[job.department, salaryDisplay + salaryLabel(job.salaryType), job.employmentType ? employmentLabels[job.employmentType] : null]
              .filter(Boolean).join(" · ")}
          </p>
        </div>

        <div className="flex flex-wrap gap-1.5 sm:gap-2 flex-shrink-0">
          <Button variant="outline" size="sm" className="px-2 text-xs h-7 gap-1 sm:h-8 sm:px-3 sm:text-sm sm:gap-1.5">
            <BarChart2 size={13} className="flex-shrink-0" />
            View Progress
          </Button>
          <Link href={`/jobs/${job._id}`} target="_blank">
            <Button variant="outline" size="sm" className="px-2 text-xs h-7 gap-1 sm:h-8 sm:px-3 sm:text-sm sm:gap-1.5">
              <ExternalLink size={13} className="flex-shrink-0" />
              Public View
            </Button>
          </Link>
          <Link href={`/employer/post-job?edit=${job._id}`}>
            <Button size="sm" className="px-2 text-xs h-7 gap-1 sm:h-8 sm:px-3 sm:text-sm sm:gap-1.5">
              <Edit3 size={13} className="flex-shrink-0" />
              Edit Job
            </Button>
          </Link>
        </div>
      </div>

      {/* ── Two-column panels ───────────────────────────────────────── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Left — Job Posting Details */}
        <div className="bg-white rounded-xl border border-gray-200 p-6">
          <h2 className="text-sm font-semibold text-gray-900 mb-5 pb-3 border-b border-gray-100">
            Job Posting Details
          </h2>
          <dl className="grid grid-cols-2 gap-x-4 gap-y-4">
            <Field label="Job Title"           value={job.title} className="col-span-2" />
            <Field label="Department"          value={job.department} />
            <Field label="Job Role"            value={job.jobRole} />
            <Field label="Location / Area"     value={job.location} />
            <Field label="Salary / Budget"     value={salaryDisplay} />
            <Field label="Salary Type"         value={salaryLabel(job.salaryType).replace("/", "").trim() || job.salaryType} />
            <Field label="Salary Max"          value={job.salaryMax ? formatCurrency(job.salaryMax) : undefined} />
            <Field label="Duration"            value={job.projectDuration} />
            <Field label="Vacancies"           value={job.jobVacancy ? `${accepted} / ${job.jobVacancy} filled` : undefined} />
            <Field label="Posted"              value={formatDate(job.createdAt)} />
            <Field label="Deadline"            value="No deadline" />
            <Field label="Applications"        value={String(job.applicantCount)} />
            <Field label="Employment Type"     value={job.employmentType ? employmentLabels[job.employmentType] : undefined} />
            <Field label="Job Type"            value={job.jobType ? job.jobType.charAt(0).toUpperCase() + job.jobType.slice(1) : undefined} />
            <Field label="Work Shift"          value={job.workShift ? shiftLabels[job.workShift] : undefined} />
            <Field label="Company"             value={job.companyName} className="col-span-2" />
            <Field label="Address"             value={job.companyAddress} className="col-span-2" />
            <Field label="Posted By"           value={job.postedBy} />
          </dl>
        </div>

        {/* Right — Requirements & Responsibilities */}
        <div className="bg-white rounded-xl border border-gray-200 p-6 space-y-6">
          <h2 className="text-sm font-semibold text-gray-900 pb-3 border-b border-gray-100">
            Responsibilities & Requirements
          </h2>

          {/* Description — only show if distinct from responsibilities */}
          {job.description && job.description.trim() !== (job.responsibilities || "").trim() && (
            <div>
              <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Description</p>
              <p className="text-sm text-gray-700 leading-relaxed whitespace-pre-line">
                {stripHtml(job.description)}
              </p>
            </div>
          )}

          {/* Responsibilities */}
          {job.responsibilities && (
            <div>
              <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Responsibilities</p>
              <p className="text-sm text-gray-700 leading-relaxed whitespace-pre-line">
                {stripHtml(job.responsibilities)}
              </p>
            </div>
          )}

          {/* Candidate requirements */}
          <div className="grid grid-cols-2 gap-3 text-sm">
            {job.experienceLevel && (
              <div className="flex items-center gap-2 text-gray-600">
                <Clock size={14} className="text-gray-400 flex-shrink-0" />
                {expLabels[job.experienceLevel] ?? job.experienceLevel}
              </div>
            )}
            {job.education && job.education !== "any" && (
              <div className="flex items-center gap-2 text-gray-600">
                <GraduationCap size={14} className="text-gray-400 flex-shrink-0" />
                {educationLabels[job.education]}
              </div>
            )}
            {job.genderPreference && job.genderPreference !== "any" && (
              <div className="flex items-center gap-2 text-gray-600">
                <User size={14} className="text-gray-400 flex-shrink-0" />
                {job.genderPreference.charAt(0).toUpperCase() + job.genderPreference.slice(1)} preferred
              </div>
            )}
          </div>

          {/* Skills */}
          {job.skills.length > 0 && (
            <div>
              <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide mb-2">Skills</p>
