"use client";

import { useEffect, useState, useCallback } from "react";
import { useSession } from "next-auth/react";
import { useSearchParams } from "next/navigation";
import { useToast } from "@/components/ui/Toast";
import { applicationsApi, jobsApi } from "@/lib/api";
import { Application, JobSeekerStats } from "@/types";
import { CardSkeleton } from "@/components/ui/Skeleton";
import { Badge, statusBadge } from "@/components/ui/Badge";
import { Avatar } from "@/components/ui/Avatar";
import { Button } from "@/components/ui/Button";
import {
  Briefcase,
  DollarSign,
  Clock,
  UserCheck,
  ArrowRight,
} from "lucide-react";
import { formatCurrency, formatRelativeTime, getGreeting, getFormattedDate } from "@/lib/utils";
import Link from "next/link";
import { ActiveProgressWidget } from "@/components/work/ActiveProgressWidget";

// ─── Stat card config ─────────────────────────────────────────────────────────

const statConfig = [
  {
    key: "activeJobs",
    label: "Active Jobs",
    icon: Briefcase,
    bg: "bg-[#edf2f7]",
    iconBg: "bg-blue-100",
    iconColor: "text-[#1e3a5f]",
    valueColor: "text-[#1e3a5f]",
  },
  {
    key: "earnings",
    label: "Total Earnings",
    icon: DollarSign,
    bg: "bg-[#edf2f7]",
    iconBg: "bg-blue-100",
    iconColor: "text-[#1e3a5f]",
    valueColor: "text-[#1e3a5f]",
    format: (v: number) => formatCurrency(v),
  },
  {
    key: "pendingApplications",
    label: "Pending Applications",
    icon: Clock,
    bg: "bg-amber-50",
    iconBg: "bg-amber-100",
    iconColor: "text-amber-600",
    valueColor: "text-amber-700",
  },
  {
    key: "hireRequests",
    label: "Proposals",
    icon: UserCheck,
    bg: "bg-orange-50",
    iconBg: "bg-orange-100",
    iconColor: "text-orange-600",
    valueColor: "text-orange-700",
  },
] as const;

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function JobSeekerDashboard() {
  const { data: session, status } = useSession();
  const searchParams = useSearchParams();
  const { error: toastError } = useToast();
  const [mounted, setMounted] = useState(false);
  const [loading, setLoading] = useState(true);
  const [applications, setApplications] = useState<Application[]>([]);

  const [stats, setStats] = useState<JobSeekerStats>({
    activeJobs: 0,
    earnings: 0,
    pendingApplications: 0,
    hireRequests: 0,
    completedJobs: 0,
  });

  useEffect(() => {
    if (searchParams?.get("error") === "employer_only") {
      toastError("Please login as an employer first");
      const url = new URL(window.location.href);
      url.searchParams.delete("error");
      window.history.replaceState({}, "", url.toString());
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams]);

  const fetchData = useCallback(async () => {
    if (!session?.user.accessToken) {
      // Token is missing — stop loading so we don't show skeleton forever
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const [appsRes, statsRes] = await Promise.all([
        applicationsApi.getMyApplications(session.user.accessToken) as Promise<{ data: Application[] }>,
        jobsApi.getJobseekerStats(session.user.accessToken) as Promise<{ data: JobSeekerStats }>,
      ]);
      setApplications(appsRes.data || []);
      setStats(statsRes.data || {
        activeJobs: 0,
        earnings: 0,
        pendingApplications: 0,
        hireRequests: 0,
        completedJobs: 0,
      });
    } catch {
      // keep empty on error
      setStats({
        activeJobs: 0,
        earnings: 0,
        pendingApplications: 0,
        hireRequests: 0,
        completedJobs: 0,
      });
    } finally {
