                    <p className="text-xs text-gray-500">{e.school} · {e.startYear}–{e.endYear || "Present"}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Sticky action bar */}
        {showActions && (
          <div className="absolute bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex flex-wrap gap-2">
            {application.status === "pending" && (
              <Button
                size="sm"
                variant="secondary"
                className="text-purple-700 bg-purple-50 hover:bg-purple-100 border border-purple-200 flex-1 sm:flex-none"
                onClick={() => { onStatusChange(application._id, "shortlisted"); }}
              >
                Shortlist
              </Button>
            )}
            <Button
              size="sm"
              className="gap-1.5 flex-1 sm:flex-none"
              onClick={() => { onStatusChange(application._id, "accepted"); onClose(); }}
            >
              <CheckCircle2 size={13} />
              Accept
            </Button>
            <Button
              size="sm"
              variant="danger"
              className="gap-1.5 flex-1 sm:flex-none"
              onClick={() => { onStatusChange(application._id, "rejected"); onClose(); }}
            >
              <XCircle size={13} />
              Reject
            </Button>
          </div>
        )}
      </aside>
    </>,
    document.body
  );
}

