"use client";

import { useState, FormEvent, useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { signIn } from "next-auth/react";
import { Eye, EyeOff, Shield, Mail, Lock } from "lucide-react";
import { Input } from "@/components/ui/Input";
import { Button } from "@/components/ui/Button";
import { RoleToggle } from "./RoleToggle";
import { useToast } from "@/components/ui/Toast";
import { UserRole } from "@/types";
import { cn } from "@/lib/utils";
import Link from "next/link";

const buttonLabel: Record<UserRole, string> = {
  jobseeker: "Sign In as Freelancer",
  employer:  "Sign In as Employer",
  admin:     "Sign In as Admin",
};

function SignInFormContent() {
  const router       = useRouter();
  const searchParams = useSearchParams();
  const { error: showError } = useToast();

  // Pre-select role from ?role= query param (e.g. /sign-in?role=admin)
  const roleParam = searchParams.get("role") as UserRole | null;
  const initialRole: UserRole =
    roleParam === "employer" || roleParam === "admin" ? roleParam : "jobseeker";

  const [role,         setRole]         = useState<UserRole>(initialRole);
  const [email,        setEmail]        = useState("");
  const [password,     setPassword]     = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading,      setLoading]      = useState(false);

  // If URL param changes, sync it
  useEffect(() => {
    if (roleParam === "employer" || roleParam === "admin" || roleParam === "jobseeker") {
      setRole(roleParam);
    }
  }, [roleParam]);

  // Whether to show the Admin tab in the toggle
  const showAdminTab = role === "admin" || roleParam === "admin";

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const result = await signIn("credentials", {
        email,
        password,
        role,
        redirect: false,
      });

      if (result?.error) {
        showError("Invalid email or password");
      } else {
        // Fetch session to get the actual role back from the server
        const res     = await fetch("/api/auth/session");
        const session = await res.json();
        const userRole = session?.user?.role || role;
        router.push(`/${userRole}/dashboard`);
        router.refresh();
      }
    } catch {
      showError("Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Admin mode banner */}
      {role === "admin" && (
        <div className="flex items-start gap-2.5 bg-red-50 border border-red-200 rounded-2xl px-4 py-3 text-xs text-red-700">
          <Shield size={16} className="flex-shrink-0 mt-0.5" />
          <span>
            <span className="font-bold">Admin Portal Access.</span>{" "}
            Restricted access. Authorized personnel only.
          </span>
        </div>
      )}

      <RoleToggle value={role} onChange={setRole} showAdmin={showAdminTab} />

      <div className="space-y-4">
        <Input
          label="Email address"
          type="email"
          placeholder="Enter your email address"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          autoComplete="email"
          leftIcon={<Mail size={16} className="text-gray-400" />}
        />

        <Input
          label="Password"
          type={showPassword ? "text" : "password"}
          placeholder="Enter your password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          autoComplete="current-password"
          leftIcon={<Lock size={16} className="text-gray-400" />}
          rightIcon={
            <button
              type="button"
              className="text-gray-400 hover:text-gray-600 transition-colors focus:outline-none cursor-pointer"
              onClick={() => setShowPassword(!showPassword)}
              aria-label={showPassword ? "Hide password" : "Show password"}
            >
              {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
            </button>
          }
        />
      </div>

      <div className="flex items-center justify-between text-xs">
        <label className="flex items-center gap-2 cursor-pointer group">
          <input 
            type="checkbox" 
            className="rounded border-gray-300 text-[#1e3a5f] focus:ring-[#1e3a5f] transition-all cursor-pointer w-4 h-4" 
          />
          <span className="text-gray-655 group-hover:text-gray-900 transition-colors select-none font-medium">
            Remember me
          </span>
        </label>
        <Link 
          href="/forgot-password" 
          className="text-[#1e3a5f] hover:text-[#d4a017] font-semibold transition-colors"
        >
          Forgot password?
        </Link>
      </div>

      <Button
        type="submit"
        fullWidth
        loading={loading}
        className={cn(
          "h-11 rounded-xl font-semibold transition-all transform active:scale-95 shadow-md shadow-blue-900/10",
          role === "admin" ? "bg-red-600 hover:bg-red-700" : "bg-[#1e3a5f] hover:bg-[#152a45]"
        )}
      >
        {buttonLabel[role]}
      </Button>

      {role !== "admin" && (
        <p className="text-center text-xs text-gray-550 mt-6">
          Don&apos;t have an account?{" "}
          <Link
            href={`/register?role=${role}`}
            className="text-[#1e3a5f] font-bold hover:text-[#d4a017] hover:underline transition-colors"
          >
            Create one
          </Link>
        </p>
      )}
    </form>
  );
}

export function SignInForm() {
  return (
    <Suspense fallback={<div className="h-48 flex items-center justify-center text-gray-450 text-xs">Loading form...</div>}>
      <SignInFormContent />
    </Suspense>
  );
}

"use client";

import { Application, ApplicationStatus } from "@/types";
import { Badge, statusBadge } from "@/components/ui/Badge";
import { Button } from "@/components/ui/Button";
import { Avatar } from "@/components/ui/Avatar";
import { formatDate, formatCurrency } from "@/lib/utils";
import { Star, MapPin, Eye, ClipboardList } from "lucide-react";

interface ApplicantCardProps {
  application: Application;
  onStatusChange: (id: string, status: ApplicationStatus) => void;
  onViewDetails: (application: Application) => void;
  /** Called when employer wants to see this applicant's progress updates */
  onViewProgress?: (appId: string, title: string) => void;
  /** Whether there are unseen updates — shows red dot on the progress button */
  hasUnseen?: boolean;
}

function StarRating({ rating = 4.5 }: { rating?: number }) {
  return (
    <div className="flex items-center gap-1">
      {[1, 2, 3, 4, 5].map((s) => (
        <Star
          key={s}
          size={12}
          className={s <= Math.round(rating) ? "text-yellow-400 fill-yellow-400" : "text-gray-200 fill-gray-200"}
        />
      ))}
      <span className="text-xs text-gray-400 ml-1">({0} reviews)</span>
    </div>
  );
}

export function ApplicantCard({ application, onStatusChange, onViewDetails, onViewProgress, hasUnseen }: ApplicantCardProps) {
  const applicant = typeof application.applicant === "object" ? application.applicant : null;
  const job       = typeof application.job === "object" ? application.job : null;

  const salaryDisplay = job?.salaryMax
    ? `${formatCurrency(job.salaryMax)}/mo`
    : job?.salary
    ? `${formatCurrency(job.salary)}/mo`
    : null;

  const stop = (e: React.MouseEvent) => e.stopPropagation();

  return (
    <div
      className="bg-white rounded-xl border border-gray-200 p-5 hover:shadow-md hover:border-[#1e3a5f]/20 transition-all cursor-pointer"
      onClick={() => onViewDetails(application)}
    >
      {/* ── Row 1: avatar · name · status · salary ───────────────────── */}
      <div className="flex items-start justify-between gap-3 mb-3">
        <div className="flex items-center gap-3 min-w-0">
          <Avatar
            name={applicant?.name ?? "Applicant"}
            src={applicant?.avatar}
            size="lg"
            className="flex-shrink-0"
          />
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2 mb-0.5">
              <p className="font-semibold text-gray-900 truncate">
                {applicant?.name ?? "Applicant"}
              </p>
              <Badge variant={statusBadge(application.status)}>
                {application.status.charAt(0).toUpperCase() + application.status.slice(1)}
              </Badge>
            </div>
            {job && (
              <p className="text-xs text-gray-400 truncate">
                For: <span className="text-gray-600 font-medium">{job.title}</span>
              </p>
            )}
          </div>
        </div>

        {salaryDisplay && (
          <div className="text-right flex-shrink-0">
            <p className="font-bold text-gray-900 text-sm">{salaryDisplay}</p>
            <p className="text-xs text-gray-400">Budget</p>
          </div>
        )}
      </div>

      {/* ── Row 2: title · location · experience · stars ─────────────── */}
      <div className="flex flex-wrap items-center gap-x-4 gap-y-1.5 mb-3 text-xs text-gray-500">
        {applicant?.title && (
          <span className="font-medium text-gray-700">{applicant.title}</span>
        )}
        {applicant?.location && (
          <span className="flex items-center gap-1">
            <MapPin size={11} />
            {applicant.location}
          </span>
        )}
        <StarRating />
        <span className="text-[#1e3a5f] font-medium">95% completion</span>
      </div>

      {/* ── Cover letter quote ───────────────────────────────────────── */}
      {application.coverLetter && (
        <p className="text-sm text-gray-500 italic line-clamp-2 mb-3 border-l-2 border-gray-200 pl-3">
          "{application.coverLetter}"
        </p>
      )}

      {/* ── Skills ──────────────────────────────────────────────────── */}
      {applicant?.skills && applicant.skills.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-4">
          {applicant.skills.slice(0, 5).map((skill) => (
            <span
              key={skill}
              className="px-2.5 py-0.5 rounded-full bg-gray-100 text-gray-600 text-xs border border-gray-200"
            >
              {skill}
            </span>
          ))}
          {applicant.skills.length > 5 && (
            <span className="px-2.5 py-0.5 rounded-full bg-gray-100 text-gray-400 text-xs border border-gray-200">
              +{applicant.skills.length - 5} more
            </span>
          )}
        </div>
      )}

      {/* ── Footer: date · actions ───────────────────────────────────── */}
      <div
        className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pt-3 border-t border-gray-100"
        onClick={stop}
      >
        <p className="text-xs text-gray-400">
          Applied {formatDate(application.createdAt)}
        </p>

        <div className="flex flex-wrap gap-2">
          {application.status === "pending" && (
            <>
              <Button
                size="sm"
                variant="secondary"
                className="text-purple-700 bg-purple-50 hover:bg-purple-100 border border-purple-200"
                onClick={() => onStatusChange(application._id, "shortlisted")}
              >
                Shortlist
              </Button>
              <Button
                size="sm"
                onClick={() => onStatusChange(application._id, "accepted")}
              >
                Accept
              </Button>
              <Button
                size="sm"
                variant="danger"
                onClick={() => onStatusChange(application._id, "rejected")}
              >
                Reject
              </Button>
            </>
          )}
          {application.status === "shortlisted" && (
            <>
              <Button
                size="sm"
                onClick={() => onStatusChange(application._id, "accepted")}
              >
                Accept
              </Button>
              <Button
                size="sm"
                variant="danger"
                onClick={() => onStatusChange(application._id, "rejected")}
              >
                Reject
              </Button>
            </>
          )}
          <Button
            size="sm"
            variant="outline"
            className="gap-1.5"
            onClick={() => onViewDetails(application)}
          >
            <Eye size={13} />
            View Details
          </Button>

          {/* Progress button — accepted applications only */}
          {application.status === "accepted" && onViewProgress && (
            <Button
              size="sm"
              variant="outline"
              className="gap-1.5 relative border-green-600 text-green-700 hover:bg-green-50"
              onClick={() => {
                const job = typeof application.job === "object" ? application.job : null;
                const applicant = typeof application.applicant === "object" ? application.applicant : null;
                const title = applicant?.name
                  ? `${applicant.name}${job ? ` · ${job.title}` : ""}`
                  : job?.title ?? "Application";
                onViewProgress(application._id, title);
              }}
            >
              <ClipboardList size={13} />
              Progress
              {hasUnseen && (
                <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full" aria-label="Unseen updates" />
              )}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

