                  <div className="flex items-start gap-3.5 min-w-0">
                    <div className="w-12 h-12 bg-[#1e3a5f] text-white rounded-xl flex items-center justify-center font-bold text-sm flex-shrink-0">
                      {formData.companyName.slice(0, 2).toUpperCase() || "CO"}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-semibold text-gray-900 break-words">
                        {formData.companyName || "—"}
                      </p>
                      <p className="text-sm text-gray-500 mt-0.5 break-words">
                        {formData.companyAddress || "No location set"}
                      </p>
                      <p className="text-xs text-gray-500 mt-1">
                        Posted by:{" "}
                        <span className="font-medium text-gray-700">
                          {formData.postedBy}
                        </span>
                      </p>
                    </div>
                  </div>
                  <Link
                    href="/employer/profile"
                    className="text-[#1e3a5f] text-sm font-medium hover:underline flex-shrink-0 self-start sm:self-auto"
                  >
                    Edit Profile →
                  </Link>
                </div>

                <p className="text-sm text-gray-500 mt-3">
                  This information is pulled from your{" "}
                  <Link
                    href="/employer/profile"
                    className="text-[#1e3a5f] hover:underline font-medium"
                  >
                    company profile
                  </Link>
                  . Update it there to reflect here.
                </p>
              </div>
            )}

            {/* Navigation Buttons */}
            <div className="flex flex-col sm:flex-row justify-between gap-3 pt-6 border-t border-gray-200">
              <Button
                type="button"
                variant="secondary"
                onClick={prevStep}
                disabled={currentStep === 1}
                className="w-full sm:w-auto"
              >
                Back
              </Button>

              {currentStep < 3 ? (
                <Button
                  key="continue-btn"
                  type="button"
                  onClick={nextStep}
                  className="w-full sm:w-auto"
                >
                  Continue
                </Button>
              ) : (
                <Button
                  key="submit-btn"
                  type="submit"
                  loading={loading}
                  className="bg-[#1e3a5f] hover:bg-[#152a45] w-full sm:w-auto"
                >
                  {editTaskId ? "Save Changes" : "Post Task"}
                </Button>
              )}
            </div>
          </form>
        </div>

        <div className="hidden lg:block w-80 flex-shrink-0 sticky top-6">
          <div className="bg-white rounded-xl border border-gray-200 p-5">
            {previewCard}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Job } from "@/types";
import { Avatar } from "@/components/ui/Avatar";
import { MapPin, CheckCircle2, Bookmark, Star, Clock } from "lucide-react";
import { formatCurrency, salaryLabel, formatRelativeTime, cn } from "@/lib/utils";
import Link from "next/link";
import { useRouter } from "next/navigation";

interface JobCardProps {
  job: Job;
  applied: boolean;
  saved: boolean;
  onApply: (job: Job) => void;
  onToggleSave: (jobId: string) => void;
  userRole?: string;
  variant?: "card" | "list";
}

export function JobCard({
  job,
  applied,
  saved,
  onApply,
  onToggleSave,
  userRole,
}: JobCardProps) {
  const router = useRouter();
  const employer = typeof job.employer === "object" ? job.employer : null;
  const companyName = employer?.company || employer?.name || job.companyName || "Winkget Express";
  const location = employer?.location || job.location || "Lucknow";
  const salary = job.salaryMax ?? job.salary;

  const handleCardClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    if (target.closest("button") || target.closest("a")) return;
    router.push(`/jobs/${job._id}`);
  };

  const workModeBadge =
    job.jobType === "hybrid" ? "Hybrid"
      : job.location?.toLowerCase().includes("remote") ? "Remote"
        : job.jobType === "office" ? "On-site"
          : job.location || "Hybrid";

  const isJobseeker = !userRole || userRole === "jobseeker";

  const salaryTypeLabel =
    job.salaryType === "fixed" ? "Fixed" :
      job.salaryType === "monthly" ? "Monthly" :
        job.salaryType === "hourly" ? "Hourly" :
          job.salaryType === "annual" ? "Annual" : "Project";

  const employmentTypeLabel =
    job.employmentType === "fullTime" ? "Full Time" :
      job.employmentType === "partTime" ? "Part Time" :
        job.employmentType === "contract" ? "Contract" :
          job.employmentType === "internship" ? "Internship" : "Full Time";

  const expLevelLabel =
    job.experienceLevel === "fresher" ? "Fresher" :
      job.experienceLevel === "0-1" ? "0-1 Years" :
        job.experienceLevel === "1-2" ? "1-2 Years" :
          job.experienceLevel === "2-5" ? "2-5 Years" :
            job.experienceLevel === "5-10" ? "5-10 Years" :
              job.experienceLevel === "10+" ? "10+ Years" : "Fresher";

  const initial = companyName.charAt(0).toUpperCase() || "W";
  const formattedSalary = `${formatCurrency(salary)}${salaryLabel(job.salaryType)}`;
  const description = job.description || job.responsibilities || "Plan and execute marketing campaigns across multiple channels. Create engaging content for social media, email, and promotional materials.";

  const ratingAvg = employer?.ratingAvg || 0;
  const ratingCount = employer?.ratingCount || 0;

  return (
    <div
      onClick={handleCardClick}
      className="group relative bg-white rounded-2xl border border-gray-200/90 p-4 sm:p-5 hover:shadow-md hover:border-blue-200 transition-all duration-200 flex flex-col justify-between w-full h-full flex-1 overflow-hidden cursor-pointer"
    >
      <div className="flex-1 flex flex-col">
        {/* Top Header Row */}
        <div className="flex items-start justify-between gap-2.5">
